$(function(){"use strict";function initMetisMenu(){$("#side-menu").metisMenu()}function initLeftMenuCollapse(){$("#vertical-menu-btn").on("click",function(event){event.preventDefault();$("body").toggleClass("sidebar-enable");if($(window).width()>=992){$("body").toggleClass("vertical-collpsed")}else{$("body").removeClass("vertical-collpsed")}})}function initActiveMenu(){const pageUrl=window.location.href;$("#sidebar-menu a").each(function(){if(this.href===pageUrl){const $link=$(this).parent("span").length?$(this).closest("li").find("> a"):$(this);$link.addClass("active");const $li=$link.parent();$li.addClass("mm-active");$li.parents("ul").addClass("mm-show");$li.parents("li").addClass("mm-active")}})}function initMenuItem(){const pageUrl=window.location.href.split(/[?#]/)[0];$(".navbar-nav a").each(function(){if(this.href===pageUrl){const $link=$(this).parent("span").length?$(this).closest("li").find("> a"):$(this);$link.addClass("active");$link.parents("li").addClass("active")}})}function initDropdownMenu(){$(".dropdown-menu a.dropdown-toggle").on("click",function(e){if(!$(this).next().hasClass("show")){$(this).parents(".dropdown-menu").first().find(".show").removeClass("show")}var $subMenu=$(this).next(".dropdown-menu");$subMenu.toggleClass("show");return false})}function initComponents(){$(function(){$('[data-toggle="tooltip"]').tooltip()});$(function(){$('[data-toggle="popover"]').popover()})}function init(){initMetisMenu();initLeftMenuCollapse();initActiveMenu();initMenuItem();initDropdownMenu();initComponents()}init()});